// Get all data
const inquiries = $('Read Inquiries').all().map(r => r.json);
const complaints = $('Read Complaints').all().map(r => r.json);

// Get today's date
const now = new Date();
const today = now.toLocaleDateString('en-PK', { timeZone: 'Asia/Karachi' });
const yesterday = new Date(now - 24 * 60 * 60 * 1000)
  .toLocaleDateString('en-PK', { timeZone: 'Asia/Karachi' });

// Helper: check if timestamp is from last 24 hours
function isRecent(timestamp) {
  if (!timestamp) return false;
  try {
    const parts = timestamp.split(', ');
    const dateParts = parts[0].split('/');
    const usDate = `${dateParts[1]}/${dateParts[0]}/${dateParts[2]} ${parts[1]}`;
    const date = new Date(usDate);
    const hoursDiff = (now - date) / (1000 * 60 * 60);
    return hoursDiff <= 24;
  } catch(e) { return false; }
}

// ── INQUIRIES ANALYSIS ──
const todayInquiries = inquiries.filter(r => isRecent(r['Timestamp']));
const totalInquiries = todayInquiries.length;

// Count by category
const categoryCount = {};
todayInquiries.forEach(r => {
  const cat = r['Category'] || 'OTHER';
  categoryCount[cat] = (categoryCount[cat] || 0) + 1;
});

// Hot leads (HIGH buying intent)
const hotLeads = todayInquiries.filter(r => r['Buying Intent'] === 'HIGH');

// Follow up status
const followedUp = inquiries.filter(r => r['Status'] === 'FOLLOWED_UP').length;
const coldLeads = inquiries.filter(r => r['Status'] === 'COLD').length;

// ── COMPLAINTS ANALYSIS ──
const todayComplaints = complaints.filter(r => isRecent(r['Timestamp']));
const totalComplaints = todayComplaints.length;

const openComplaints = complaints.filter(r => r['Status'] === 'OPEN').length;
const resolvedToday = complaints.filter(r => 
  r['Status'] === 'RESOLVED' && isRecent(r['Timestamp'])
).length;

const criticalComplaints = complaints.filter(r => 
  r['Urgency'] === 'CRITICAL' && r['Status'] === 'OPEN'
).length;

const highComplaints = complaints.filter(r => 
  r['Urgency'] === 'HIGH' && r['Status'] === 'OPEN'
).length;

// Category breakdown for complaints
const complaintCategories = {};
todayComplaints.forEach(r => {
  const cat = r['Category'] || 'OTHER';
  complaintCategories[cat] = (complaintCategories[cat] || 0) + 1;
});

// ── BUILD REPORT TEXT ──
const categoryBreakdown = Object.entries(categoryCount)
  .map(([k, v]) => `  • ${k}: ${v}`)
  .join('\n');

const hotLeadsList = hotLeads.slice(0, 3)
  .map(r => `  • ${r['Client Name'] || 'Unknown'} — ${r['Category']} — ${r['Summary'] || ''}`)
  .join('\n');

const complaintBreakdown = Object.entries(complaintCategories)
  .map(([k, v]) => `  • ${k}: ${v}`)
  .join('\n');

// ── ACTION ITEMS ──
const actionItems = [];
if (criticalComplaints > 0) actionItems.push(`🔴 ${criticalComplaints} CRITICAL complaint(s) still OPEN — immediate action needed`);
if (highComplaints > 0) actionItems.push(`🟠 ${highComplaints} HIGH priority complaint(s) pending`);
if (hotLeads.length > 0) actionItems.push(`💰 ${hotLeads.length} hot lead(s) with HIGH buying intent — follow up today`);
if (coldLeads > 0) actionItems.push(`❄️ ${coldLeads} lead(s) marked COLD — consider direct phone call`);
if (totalInquiries === 0) actionItems.push(`📭 No new inquiries today — consider running a promotion`);

const actionItemsText = actionItems.length > 0 
  ? actionItems.join('\n') 
  : '✅ Everything looks good today!';

// ── FINAL REPORT ──
const reportDate = now.toLocaleDateString('en-PK', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric',
  timeZone: 'Asia/Karachi'
});

const reportTime = now.toLocaleTimeString('en-PK', { 
  timeZone: 'Asia/Karachi',
  hour: '2-digit',
  minute: '2-digit'
});

return [{
  json: {
    reportDate,
    reportTime,
    // Inquiries
    totalInquiries,
    categoryBreakdown: categoryBreakdown || '  • No inquiries today',
    hotLeadsCount: hotLeads.length,
    hotLeadsList: hotLeadsList || '  • None today',
    followedUp,
    coldLeads,
    // Complaints
    totalComplaints,
    openComplaints,
    criticalComplaints,
    highComplaints,
    resolvedToday,
    complaintBreakdown: complaintBreakdown || '  • No complaints today',
    // Actions
    actionItems: actionItemsText,
    // Raw counts for summary
    totalAllInquiries: inquiries.length,
    totalAllComplaints: complaints.length
  }
}];

